/**
 * Nightly prune of abandoned DCR client registrations.
 *
 * MCP hosts that use RFC 8252 §7.3 loopback redirects (Claude Code,
 * Cursor, Windsurf, …) do a fresh Dynamic Client Registration per auth
 * attempt — each mints a new public `client_id` on an ephemeral
 * `http://localhost:<port>/callback`. Attempts that are retried,
 * cancelled, or superseded leave behind a registration with no grant.
 * `workers-oauth-provider` never expires client records, so without a
 * sweep these accumulate forever and clutter the admin viewer.
 *
 * Policy (see `isPrunableClient`): delete a client iff it is PUBLIC
 * (token_endpoint_auth_method='none'), has ZERO grants, and was
 * registered more than `olderThanDays` ago. Confidential clients
 * (stable hosted redirects, e.g. claude.ai) are never auto-pruned even
 * with zero grants — a missing grant there reads as "not used yet",
 * not "abandoned".
 *
 * Fail-closed: if the grant index is incomplete (a per-user
 * listUserGrants read failed, so a real grant could be invisible) we
 * delete NOTHING this run and report it. A legitimate client must never
 * be deleted because a transient KV read made it look orphaned.
 */

import type { Env } from '../env'
import { buildUserGrantIndex, type OAuthHelpers } from './client-grants'
import { errMessage } from '../util/errors'

const SECONDS_PER_DAY = 86400

export interface PruneClientsResult {
  scanned: number
  /** Clients matching the prune policy. */
  orphans: number
  deleted: number
  /** deleteClient calls that threw. */
  failed: number
  /** True when we declined to delete because the grant index undercounts. */
  skippedIncompleteIndex: boolean
  deletedIds: string[]
}

/** Minimal shape of a client record needed to decide prunability. */
interface ClientLike {
  clientId: string
  tokenEndpointAuthMethod: string
  registrationDate?: number | null
}

/**
 * Pure prune predicate. `grantIndex` keys are clients that hold ≥1
 * grant; absence ⇒ zero grants. `cutoffSeconds` is the youngest
 * registration timestamp we'll still delete (older = prunable).
 */
export function isPrunableClient(
  client: ClientLike,
  grantIndex: ReadonlyMap<string, unknown>,
  cutoffSeconds: number
): boolean {
  if (client.tokenEndpointAuthMethod !== 'none') return false // confidential
  if (grantIndex.has(client.clientId)) return false // has grants
  // No registrationDate ⇒ can't age it ⇒ keep (don't delete blind).
  if (typeof client.registrationDate !== 'number') return false
  return client.registrationDate < cutoffSeconds
}

/**
 * Core loop, decoupled from the grant-index build so it's unit-testable
 * with a mock helpers + a plain Map. Paginates all clients and deletes
 * the prunable ones best-effort.
 */
export async function pruneClientsByPolicy(
  helpers: Pick<OAuthHelpers, 'listClients' | 'deleteClient'>,
  grantIndex: ReadonlyMap<string, unknown>,
  cutoffSeconds: number
): Promise<Omit<PruneClientsResult, 'skippedIncompleteIndex'>> {
  let scanned = 0
  let orphans = 0
  let deleted = 0
  let failed = 0
  const deletedIds: string[] = []

  let cursor: string | undefined
  let pages = 0
  do {
    const page = await helpers.listClients({ limit: 200, cursor })
    for (const client of page.items) {
      scanned++
      if (!isPrunableClient(client, grantIndex, cutoffSeconds)) continue
      orphans++
      try {
        await helpers.deleteClient(client.clientId)
        deleted++
        deletedIds.push(client.clientId)
      } catch (err) {
        failed++
        console.warn(
          `[prune-clients] deleteClient(${client.clientId}) failed:`,
          errMessage(err)
        )
      }
    }
    cursor = page.cursor
    // Safety backstop against an ill-behaved cursor — 50×200 = 10k
    // clients, far beyond any realistic registration count.
    if (++pages > 50) {
      console.warn('[prune-clients] stopped after 50 pages; cursor may be looping')
      break
    }
  } while (cursor)

  return { scanned, orphans, deleted, failed, deletedIds }
}

export async function pruneOrphanOAuthClients(
  env: Env,
  helpers: OAuthHelpers,
  opts: { olderThanDays: number; now?: number }
): Promise<PruneClientsResult> {
  const nowSeconds = opts.now ?? Math.floor(Date.now() / 1000)
  const cutoff = nowSeconds - opts.olderThanDays * SECONDS_PER_DAY

  const { index, complete } = await buildUserGrantIndex(env, helpers)
  if (!complete) {
    return {
      scanned: 0,
      orphans: 0,
      deleted: 0,
      failed: 0,
      skippedIncompleteIndex: true,
      deletedIds: []
    }
  }

  const core = await pruneClientsByPolicy(helpers, index, cutoff)
  return { ...core, skippedIncompleteIndex: false }
}

/**
 * Single source of truth for the OAuthProvider config.
 *
 * `index.ts` constructs the live provider; admin tooling (e.g. the
 * OAuth-clients viewer) constructs a read-only `OAuthHelpers` instance
 * via `getOAuthApi(opts, env)` and MUST use the identical KV+path
 * config so the helpers point at the same data the live provider
 * wrote. Extracted here so we can't drift.
 *
 * The `defaultHandler` is plumbed through as a parameter because
 * helpers paths (listClients, lookupClient, etc.) never invoke it —
 * admin code can pass a stub, while `index.ts` passes the real Hono
 * app.
 */

import type { ExportedHandler } from '@cloudflare/workers-types'
import type { OAuthProviderOptions } from '@cloudflare/workers-oauth-provider'
import { McpSessionDO } from '../mcp/session-do'
import type { Env } from '../env'

const NOOP_HANDLER: ExportedHandler<Env> = {
  fetch: () => new Response('not used by admin helpers', { status: 500 })
}

export function oauthProviderOptions(
  defaultHandler: ExportedHandler<Env> = NOOP_HANDLER
): OAuthProviderOptions<Env> {
  // apiHandlers requires ExportedHandlerWithFetch (Required fetch);
  // our handlers carry `fetch` at the value level but their declared
  // types don't line up exactly, so the whole map is cast once.
  const apiHandlers = {
    '/mcp': McpSessionDO.serve('/mcp', { binding: 'MCP_SESSION_DO' }),
    '/sse': McpSessionDO.serveSSE('/sse', { binding: 'MCP_SESSION_DO' })
  } as OAuthProviderOptions<Env>['apiHandlers']
  return {
    apiHandlers,
    defaultHandler,
    authorizeEndpoint: '/oauth/authorize',
    tokenEndpoint: '/oauth/token',
    clientRegistrationEndpoint: '/oauth/register',
    scopesSupported: ['mcp']
  }
}

import { OAuthProvider, getOAuthApi } from '@cloudflare/workers-oauth-provider'
import type { Env } from './env'
import { queueKind } from './queues/route'
import { app } from './app'
import { oauthProviderOptions } from './oauth/provider-config'
import { usageConsumer } from './queues/usage-consumer'
import { reindexConsumer } from './queues/reindex-consumer'
import { gitSyncConsumer } from './queues/git-sync-consumer'
import { jobsConsumer } from './queues/jobs-consumer'
import { pruneUsageEvents } from './db/queries/usage'
import { clearAsyncJobResults, pruneAsyncJobs } from './db/queries/async-jobs'
import { pruneOrphanOAuthClients } from './oauth/prune-clients'
import { listDueGitSyncs } from './git/sync'
import { audit } from './audit/log'
import { notify } from './ops/alert'
import { LAST_CRON_KV_KEY } from './ops/cron-heartbeat'
import { withHsts } from './util/security-headers'
import { isMcpPathOnWrongHost } from './util/mcp-host'
import { errMessage } from './util/errors'
import { keepWarmUserCredentials } from './upstream/keep-warm'
import { recordJobRun } from './ops/job-runs'
import { pruneJobRuns } from './db/queries/job-runs'

export { McpSessionDO } from './mcp/session-do'
export { DocRoomDO } from './collab/doc-room-do'

// Route mounting lives in `app.ts` — this module only wraps the composed
// Hono app in the OAuthProvider and the worker handler (HSTS + queue +
// scheduled).

// OAuthProvider wraps the worker's fetch. It implements /oauth/token,
// /oauth/register, /.well-known/oauth-authorization-server, and gates
// /mcp + /sse on a valid bearer token. Everything else falls through
// to the Hono app (default handler). Provider options live in
// `oauth/provider-config.ts` so admin tooling can construct a
// read-only `OAuthHelpers` against the identical config.
const oauthProvider = new OAuthProvider<Env>(
  oauthProviderOptions({ fetch: app.fetch as ExportedHandler<Env>['fetch'] })
)

const worker: ExportedHandler<Env> = {
  // HSTS on every worker-served response (asset responses get it from
  // dist/_headers — see util/security-headers.ts). Skipped on localhost so
  // dev doesn't pin the browser's whole `localhost` to HTTPS.
  fetch: async (req, env, ctx) => {
    // Host-scope the machine MCP surface: when a dedicated MCP host is
    // configured, the browser host 404s /mcp,/sse,/cli instead of answering
    // with a confusing `invalid_token` (a past-Access user has no MCP bearer).
    // No-op for single-host deployments. See util/mcp-host.ts.
    if (isMcpPathOnWrongHost(req, env)) {
      return withHsts(req, Response.json({ error: 'not_found' }, { status: 404 }))
    }
    return withHsts(req, await oauthProvider.fetch(req, env, ctx))
  },
  async queue(batch, env, ctx) {
    // Match on the type SUFFIX, not an exact name: queue names are
    // deployment-specific (tenants prefix them with the worker name, e.g.
    // `ctxlayer-acme-usage`). See queues/route.ts. Matching exact base
    // names silently broke usage/reindex/git-sync on every tenant.
    switch (queueKind(batch.queue)) {
      case 'usage':
        return usageConsumer(batch, env, ctx)
      case 'reindex':
        return reindexConsumer(batch, env, ctx)
      case 'git-sync':
        return gitSyncConsumer(batch, env, ctx)
      case 'jobs':
        return jobsConsumer(batch, env, ctx)
    }
    // A configured consumer with no code branch = deploy/config skew. Retry
    // (bounded by max_retries in wrangler.toml) rather than silently drop, and
    // alert so it's not invisible.
    console.error(`unknown queue: ${batch.queue}`)
    await notify(env, { level: 'error', event: 'queue.unknown', detail: String(batch.queue) })
    for (const msg of batch.messages) msg.retry()
  },
  async scheduled(controller, env, ctx) {
    // Liveness heartbeat for /api/health — any cron firing refreshes it, so a
    // stalled scheduler becomes visible (it otherwise emits nothing at all).
    ctx.waitUntil(
      env.OAUTH_KV.put(
        LAST_CRON_KV_KEY,
        String(Math.floor(controller.scheduledTime / 1000))
      ).catch((e) => console.error('[cron] heartbeat write failed', e))
    )
    // Hourly cron (`0 * * * *`): git-sync due-check. Enqueue one message per
    // enabled source whose sync_interval has elapsed AND that has an
    // unattended credential path: shared_bearer, or a user_* read strategy
    // with a self-designated sync identity (the message carries that userId
    // so the consumer resolves their stored token). See listDueGitSyncs.
    if (controller.cron === '0 * * * *') {
      ctx.waitUntil(
        (async () => {
          try {
            await recordJobRun(env, 'git-sync-due', async () => {
              const nowSec = Math.floor(controller.scheduledTime / 1000)
              const { due, total } = await listDueGitSyncs(env, nowSec)
              for (const d of due) {
                await env.GIT_SYNC_QUEUE.send(
                  d.userId ? { sourceId: d.sourceId, userId: d.userId } : { sourceId: d.sourceId }
                )
              }
              console.log(`[cron] git-sync: queued ${due.length}/${total} source(s)`)
              return { summary: { queued: due.length, total } }
            })
          } catch (err) {
            const m = errMessage(err)
            console.error(`[cron] git-sync due-check failed: ${m}`)
            await notify(env, { level: 'error', event: 'cron.git_sync_failed', detail: m })
          }
        })()
      )
      return
    }

    // Nightly cron (`0 3 * * *`). Each task is independent and wrapped
    // in its own try/catch + waitUntil so a slow/failed one can't time
    // out the trigger or starve the others.

    // 1. Prune raw usage_events older than 30 days (rollups stay forever).
    ctx.waitUntil(
      (async () => {
        try {
          await recordJobRun(env, 'usage-prune', async () => {
            const removed = await pruneUsageEvents(env, 30)
            console.log(`[cron] pruned ${removed} usage_events rows older than 30d`)
            return { summary: { removed } }
          })
        } catch (err) {
          const m = errMessage(err)
          console.error(`[cron] usage_events prune failed: ${m}`)
          await notify(env, { level: 'error', event: 'cron.usage_prune_failed', detail: m })
        }
      })()
    )

    // 1b. async_jobs two-tier retention: drop the heavy result_json blob after
    // 1 day (retry-warm is 15 min; polling is a live action), but keep the
    // lightweight row for 30 days so the admin async-usage panel matches the
    // usage_events retention window, then delete.
    ctx.waitUntil(
      (async () => {
        try {
          await recordJobRun(env, 'async-retention', async () => {
            const cleared = await clearAsyncJobResults(env, 24 * 60 * 60)
            const removed = await pruneAsyncJobs(env, 30 * 24 * 60 * 60)
            console.log(
              `[cron] async_jobs: cleared ${cleared} result blobs (>1d), pruned ${removed} rows (>30d)`
            )
            return { summary: { cleared, removed } }
          })
        } catch (err) {
          const m = errMessage(err)
          console.error(`[cron] async_jobs prune failed: ${m}`)
          await notify(env, { level: 'error', event: 'cron.async_jobs_prune_failed', detail: m })
        }
      })()
    )

    // 2. Prune abandoned DCR client registrations: public, zero-grant,
    // older than 1 day (the loopback-OAuth retry detritus). Fail-closed
    // if the grant index is incomplete — see oauth/prune-clients.ts.
    ctx.waitUntil(
      (async () => {
        try {
          await recordJobRun(env, 'oauth-client-prune', async () => {
            const helpers = getOAuthApi<Env>(oauthProviderOptions(), env)
            const r = await pruneOrphanOAuthClients(env, helpers, { olderThanDays: 1 })
            if (r.skippedIncompleteIndex) {
              console.warn('[cron] oauth-client prune skipped: grant index incomplete')
              return { status: 'partial' as const, summary: { skipped: 'incomplete_grant_index' } }
            }
            console.log(
              `[cron] pruned ${r.deleted}/${r.orphans} orphan oauth clients ` +
                `(scanned ${r.scanned}, ${r.failed} delete failures)`
            )
            // Same summary row the admin-initiated prune writes;
            // audit_log.actor_id is un-FK'd TEXT, so the sentinel is safe.
            if (r.deleted > 0) {
              await audit(env, {
                actorId: 'cron',
                action: 'oauth_client.prune',
                meta: {
                  scanned: r.scanned,
                  orphans: r.orphans,
                  deleted: r.deleted,
                  failed: r.failed,
                  deletedIds: r.deletedIds
                }
              })
            }
            return {
              status: r.failed > 0 ? ('partial' as const) : ('ok' as const),
              summary: { scanned: r.scanned, orphans: r.orphans, deleted: r.deleted, failed: r.failed }
            }
          })
        } catch (err) {
          const m = errMessage(err)
          console.error(`[cron] oauth-client prune failed: ${m}`)
          await notify(env, { level: 'error', event: 'cron.oauth_prune_failed', detail: m })
        }
      })()
    )

    // 3. Keep-warm long-idle user_oauth refresh tokens so provider
    // inactivity windows don't silently kill them; un-preventable deaths
    // (scope change, revocation) surface as next-morning needsReauth
    // flags instead of mid-task surprises. Cadence + batch are the
    // rotation-spend safety knobs — see upstream/keep-warm.ts.
    ctx.waitUntil(
      (async () => {
        try {
          await recordJobRun(env, 'keep-warm', async () => {
            const nowSec = Math.floor(controller.scheduledTime / 1000)
            const r = await keepWarmUserCredentials(env, nowSec)
            if (r.due > 0) {
              console.log(`[cron] keep-warm: ${r.warmed}/${r.due} refreshed, ${r.failed} failed`)
            }
            return { status: r.failed > 0 ? ('partial' as const) : ('ok' as const), summary: r }
          })
        } catch (err) {
          const m = errMessage(err)
          console.error(`[cron] keep-warm failed: ${m}`)
          await notify(env, { level: 'error', event: 'cron.keep_warm_failed', detail: m })
        }
      })()
    )

    // 4. Prune the job-runs ledger itself (90d) — recorded like any task.
    ctx.waitUntil(
      (async () => {
        try {
          await recordJobRun(env, 'jobs-prune', async () => {
            const removed = await pruneJobRuns(env, 90 * 24 * 60 * 60)
            return { summary: { removed } }
          })
        } catch (err) {
          console.error(`[cron] job-runs prune failed: ${errMessage(err)}`)
        }
      })()
    )
  }
}

export default worker

/**
 * clientId → user-grant[] index, shared by the OAuth-clients admin
 * viewer (`api/admin-oauth-clients.ts`) and the orphan-client prune
 * (`oauth/prune-clients.ts`).
 *
 * The SDK has no inverse "grants for client" lookup, so we fan
 * `OAuthHelpers.listUserGrants` over every ctxlayer user in parallel
 * and group by `clientId`. A client absent from the returned map has
 * zero grants — which is exactly the signal both callers need (the
 * viewer renders "none"; the prune treats it as an abandoned
 * registration).
 *
 * Per-user failures are swallowed so one bad read can't fail the admin
 * page — but we surface a `complete` flag alongside the index. That
 * matters for the prune: a swallowed failure makes a user's real grants
 * LOOK like zero, which would make a legitimate client look orphaned.
 * The prune therefore refuses to delete anything when `complete` is
 * false (fail-closed); the viewer ignores the flag and shows the
 * best-effort index.
 *
 * Each (client, user) pair appears once; we keep the earliest
 * `createdAt` as `grantedAt` — the original authorisation moment, which
 * is what the admin cares about (refresh exchanges create new grant
 * rows over time).
 */

import type { getOAuthApi } from '@cloudflare/workers-oauth-provider'
import type { OAuthClientUserRef } from '@ctxlayer/shared'
import type { Env } from '../env'
import { listUserRefs } from '../db/queries/users'
import { errMessage } from '../util/errors'

export type OAuthHelpers = ReturnType<typeof getOAuthApi<Env>>

export interface UserGrantIndex {
  /** clientId → users who hold a grant on it. Absent key = zero grants. */
  index: Map<string, OAuthClientUserRef[]>
  /** False if any per-user listUserGrants read failed (index undercounts). */
  complete: boolean
}

export async function buildUserGrantIndex(
  env: Env,
  helpers: OAuthHelpers
): Promise<UserGrantIndex> {
  const users = await listUserRefs(env)
  if (users.length === 0) return { index: new Map(), complete: true }
  const perUser = await Promise.all(
    users.map(async (u) => {
      try {
        // listUserGrants is paginated; we pull the first page only
        // since our scale is bounded. Promote to full pagination if
        // a single user ever accumulates >200 grants (unlikely).
        const page = await helpers.listUserGrants(u.id, { limit: 200 })
        return { user: u, grants: page.items, ok: true }
      } catch (err) {
        console.warn(
          `[client-grants] listUserGrants(${u.id}) failed:`,
          errMessage(err)
        )
        return { user: u, grants: [], ok: false }
      }
    })
  )

  const complete = perUser.every((r) => r.ok)
  const index = new Map<string, OAuthClientUserRef[]>()
  for (const { user, grants } of perUser) {
    for (const g of grants) {
      const list = index.get(g.clientId) ?? []
      const existing = list.find((ref) => ref.userId === user.id)
      if (existing) {
        if (g.createdAt < existing.grantedAt) existing.grantedAt = g.createdAt
      } else {
        list.push({
          userId: user.id,
          email: user.email,
          name: user.name,
          grantedAt: g.createdAt
        })
      }
      index.set(g.clientId, list)
    }
  }
  // Stable ordering per client — earliest grant first.
  for (const list of index.values()) list.sort((a, b) => a.grantedAt - b.grantedAt)
  return { index, complete }
}

