// without giving it a label/colour here is a COMPILE error rather than a
// silent fall-through to the raw slug with an undefined colour. Lookups still
// take a plain string: `UsageErrorRow.code` is deliberately loose so a newer
// worker's response can't fail an older SPA's parse.
const CODE_LABEL: Record<UsageErrorCode, string> = {
  timeout: 'Timeout',
  upstream_5xx: 'Upstream 5xx',
  upstream_4xx: 'Upstream 4xx',
  upstream_auth: 'Auth',
  upstream_unreachable: 'Unreachable',
  upstream_error: 'Upstream error',
  local_error: 'Local error',
  // GitHub org-access 403s the proxy replaces with a first-party nudge
  // (mcp/github-nudges.ts githubOrgAccessNudge) — grouped as one family below.
  saml_sso_required: 'SAML SSO',
  org_ip_allow_list: 'IP allow list',
  org_oauth_app_restricted: 'OAuth app'
}

const CODE_COLOR: Record<UsageErrorCode, string> = {
  timeout: 'yellow',
  upstream_5xx: 'red',
  upstream_4xx: 'orange',
  upstream_auth: 'red',
  upstream_unreachable: 'grape',
  upstream_error: 'gray',
  local_error: 'blue',
  // One shared hue so the org-access family reads as a group at a glance.
  saml_sso_required: 'violet',
  org_ip_allow_list: 'violet',
  org_oauth_app_restricted: 'violet'
}

function codeLabel(code: string): string {
  return (CODE_LABEL as Record<string, string>)[code] ?? code
}

