export function upstreamHealth(
  u: Pick<UserUpstreamSummary, 'connected' | 'needsReauth' | 'authExpiresAt'>,
  nowSec: number
): UpstreamHealth {
  if (!u.connected) {
    return {
      kind: 'disconnected',
